    #
    # 准入立刻收紧，同时用户不至于一头雾水。
    conn = op.get_bind()
    rows = conn.execute(sa.text(
        "SELECT id, certifications FROM users "
        "WHERE certifications IS NOT NULL AND certifications != '[]'"
    )).fetchall()
    now = datetime.now(timezone.utc)
    for user_id, raw in rows:
        try:
            names = json.loads(raw) if isinstance(raw, str) else (raw or [])
        except (TypeError, ValueError):
            names = []
        for name in names:
            if not isinstance(name, str) or not name.strip():
                continue
            conn.execute(sa.text(
                "INSERT INTO certification_applications "
                "(user_id, name, holder_name, cert_number, issuer, images, status, "
                " decision_reason, created_at) "
                "VALUES (:uid, :name, '', '', '', :images, 'pending', :reason, :now)"
            ), {"uid": user_id, "name": name[:30], "images": "[]", "now": now,
                "reason": "历史自助添加的资质，需补充证件影像并经平台核验后方可生效"})
    # 清空快照字段：准入判断改读申请表，但这里也一并清掉，
    # 免得任何仍在读旧字段的代码路径被它误导
    conn.execute(sa.text("UPDATE users SET certifications = '[]'"))


